def find_min_sequence(N, M, S):
    if N == 0:
        return []

    # Build the graph
    graph = [[] for _ in range(N + 1)]
    for s in range(N):
        if S[s] == '0':
            for x in range(1, M + 1):
                if s + x <= N and S[s + x] == '0':
                    graph[s].append(s + x)

    # BFS to find the shortest path
    queue = deque([(0, [])])
    visited = set([0])

    while queue:
        current, path = queue.popleft()
        if current == N:
            return path + [M]
        for next_square in graph[current]:
            if next_square not in visited:
                visited.add(next_square)
                queue.append((next_square, path + [M]))

    return -1

