from collections import deque

def find_min_sequence(N, M, S):
    # Initialize BFS
    queue = deque([(0, [])])
    visited = set([0])
    parent = {0: None}

    while queue:
        current, path = queue.popleft()

        # If we reach the end square, reconstruct the path
        if current == N:
            sequence = path[::-1]
            return ' '.join(map(str, sequence))

        # Try all possible moves
        for x in range(1, M + 1):
            next_square = current + x
            if 0 <= next_square <= N and S[next_square] == '0' and next_square not in visited:
                visited.add(next_square)
                parent[next_square] = (current, x)
                queue.append((next_square, path + [x]))

    # If we exhaust the queue without reaching the end square, return -1
    return -1

