def find_path(K, X, Y):
    if (abs(X) + abs(Y)) % K != 0:
        return -1

    path = []
    x, y = 0, 0
    steps = 0

    while x != X or y != Y:
        if x < X:
            x += K
        elif x > X:
            x -= K
        elif y < Y:
            y += K
        elif y > Y:
            y -= K

        path.append((x, y))
        steps += 1

    return steps, path

