import sys

def read_input():
    input = sys.stdin.read
    data = input().split()
    K = int(data[0])
    X = int(data[1])
    Y = int(data[2])
    return K, X, Y

def can_reach_goal(K, X, Y):
    return (abs(X) + abs(Y)) % K == 0

def min_strokes(K, X, Y):
    if X == 0 and Y == 0:
        return 0
    if X == 0:
        return abs(Y) // K
    if Y == 0:
        return abs(X) // K
    return (abs(X) + abs(Y)) // K

def construct_path(K, X, Y):
    path = []
    if X == 0 and Y == 0:
        return path
    if X == 0:
        path.append((0, Y // K * K))
        path.append((0, Y))
        return path
    if Y == 0:
        path.append((X // K * K, 0))
        path.append((X, 0))
        return path
    path.append((X // K * K, Y // K * K))
    path.append((X, Y))
    return path

def main():
    K, X, Y = read_input()
    if not can_reach_goal(K, X, Y):
        print(-1)
        return
    s = min_strokes(K, X, Y)
    path = construct_path(K, X, Y)
    print(s)
    for x, y in path:
        print(x, y)

