MOD = 10**9 + 7

def count_permutations(n, k):
    if k > n * n:
        return 0
    if k == 0:
        return 1

    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= i:
                dp[i][j] += dp[i - 1][j - i]
            dp[i][j] %= MOD

    return dp[n][k]

