def count_permutations(n, k):
    if k > n**2:
        return 0
    if k == 0:
        return 1

    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            for p_i in range(1, i + 1):
                dp[i][j] = (dp[i][j] + dp[i-1][j - abs(i - p_i)]) % MOD

    return dp[n][k]

