from collections import deque

def can_reach(target):
    queue = deque([(0, 0)])
    visited = set([(0, 0)])
    while queue:
        x, y = queue.popleft()
        if (x, y) == target:
            return True
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))
    return False

def find_configuration(points):
    m = 1
    while True:
        for d in range(1, 10**13):
            if all(can_reach((x, y)) for x, y in points):
                return m, d
        m += 1

