def find_robot_arm(N, points):
    if N == 1:
        return 1, [1], ['R']  # Trivial case: one section to the right

    # Calculate the differences in x and y coordinates
    x_diffs = [points[i][0] for i in range(N)]
    y_diffs = [points[i][1] for i in range(N)]

    # Find the maximum x and y differences
    max_x_diff = max(x_diffs)
    max_y_diff = max(y_diffs)

    # Determine the number of sections
    m = max(max_x_diff, max_y_diff)

    # Initialize the lengths and modes
    lengths = [1] * m
    modes = ['R'] * m

    # Adjust lengths and modes to match the differences
    for i in range(m):
        if x_diffs[0] > 0:
            lengths[i] = x_diffs[0]
            modes[i] = 'R'
            x_diffs[0] -= lengths[i]
        elif y_diffs[0] > 0:
            lengths[i] = y_diffs[0]
            modes[i] = 'U'
            y_diffs[0] -= lengths[i]

    # Construct the result
    result = [m]
    result.extend(lengths)
    result.extend([''.join(modes)])

    return result

