    if N == 1:
        return 1, [0], ['L']

    for m in range(1, 41):
        for d in product(range(1, 10**13 + 1), repeat=m):
            for modes in product('LRDU', repeat=m):
                if all(can_reach_point(points[i][0], points[i][1], d, modes) for i in range(N)):
                    return m, d, modes

    return -1

