    elevator = [0] * (2 * N + 1)

    # Process the given records
    for A, B in records:
        if A != -1:
            elevator[A] += 1
        if B != -1:
            elevator[B] -= 1

    # Initialize the current number of people on the elevator
    current_people = 0

    # Iterate through the elevator array to check for consistency
    for i in range(1, 2 * N + 1):
        current_people += elevator[i]
        if current_people < 0:
