def min_bridges_to_remove(N, M, requests):
    bridges = list(range(1, N))
    removed_bridges = set()

    for a, b in requests:
        a -= 1
        b -= 1
        if a > b:
            a, b = b, a

        # Find the path between a and b
        path = []
        for i in range(a, b):
            if bridges[i] not in removed_bridges:
                path.append(bridges[i])

        # Remove the smallest bridge in the path
        if path:
            smallest_bridge = min(path)
            removed_bridges.add(smallest_bridge)

    return len(removed_bridges)

