            if seq[i] == seq[i + 1]:
                xor_val = 0
                for j in range(i, n):
                    if seq[j] == seq[i]:
                        xor_val ^= seq[j]
                        break
                if xor_val != K:
                    valid = False
                    break
        if valid:
            return seq

    return -1

