def find_induced_subgraph(N, M, edges):
    from collections import defaultdict, deque

    # Build adjacency list
    graph = defaultdict(list)
    for A, B in edges:
        graph[A].append(B)

    # Function to perform DFS and find cycles
    def dfs(node, parent, path, visited):
        visited[node] = True
        path.append(node)

        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, node, path, visited):
                    return True
            elif neighbor != parent:
                # Cycle found
                cycle = path[path.index(neighbor):]
                if len(cycle) > 1:
                    return cycle
        path.pop()
        visited[node] = False
        return False

    # Find a cycle in the graph
    visited = [False] * (N + 1)
    for i in range(1, N + 1):
        if not visited[i]:
            cycle = dfs(i, -1, [], visited)
            if cycle:
                break

    if not cycle:
        return -1

    # Extract the induced subgraph
    subgraph = set(cycle)
    subgraph_edges = []
    for u in subgraph:
        for v in graph[u]:
            if v in subgraph:
                subgraph_edges.append((u, v))

    return len(subgraph), subgraph, subgraph_edges

