def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def count_valid_paintings(N, edges, M, restrictions):
    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    for u, v in edges:
        union(parent, rank, u, v)

    for u, v in restrictions:
        rootU = find(parent, u)
        rootV = find(parent, v)
        if rootU == rootV:
            return 0

    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    dp = [[0] * (1 << N) for _ in range(N + 1)]
    dp[1][0] = 1

    def dfs(node, parent, mask):
        if dp[node][mask] != 0:
            return dp[node][mask]

        for neighbor in adj_list[node]:
            if neighbor == parent:
                continue
            new_mask = mask
            if new_mask & (1 << (node - 1)) == 0:
                new_mask |= (1 << (node - 1))
            dp[node][mask] += dfs(neighbor, node, new_mask)

        return dp[node][mask]

    result = dfs(1, -1, 0)
    return result

