from itertools import product

def dfs(graph, start, end, path, visited):
    if start == end:
        return [path]
    paths = []
    visited.add(start)
    for neighbor in graph[start]:
        if neighbor not in visited:
            paths += dfs(graph, neighbor, end, path + [neighbor], visited)
    visited.remove(start)
    return paths

def count_valid_paintings(N, edges, restrictions):
    graph = [[] for _ in range(N + 1)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    total_paintings = 2 ** (N - 1)
    valid_paintings = 0

    for coloring in product([0, 1], repeat=N - 1):
        valid = True
        for u, v in restrictions:
            paths = dfs(graph, u, v, [u], set())
            for path in paths:
                black_edge_found = False
                for i in range(len(path) - 1):
                    edge = tuple(sorted((path[i], path[i + 1])))
                    if coloring[edge[0] - 1] == 1:
                        black_edge_found = True
                        break
                if not black_edge_found:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            valid_paintings += 1

    return valid_paintings

