def count_valid_matrices(N, K, matrix):
    # Initialize the DP table
    dp = [0] * (1 << N)
    dp[0] = 1

    # Iterate over each row
    for row in matrix:
        new_dp = [0] * (1 << N)
        for state in range(1 << N):
            if dp[state] == 0:
                continue
            for i in range(N):
                if (state & (1 << i)) == 0:
                    for j in range(i + 1, N):
                        if (state & (1 << j)) == 0 and row[i] + row[j] <= K:
                            new_state = state | (1 << i) | (1 << j)
                            new_dp[new_state] = (new_dp[new_state] + dp[state]) % MOD
        dp = new_dp

    return dp[(1 << N) - 1]

