def count_abc_numbers(s):
    from collections import Counter

    # Count occurrences of A, B, C, and ?
    count = Counter(s)
    a_count = count['A']
    b_count = count['B']
    c_count = count['C']
    q_count = count['?']

    # Calculate the number of valid triples (i, j, k)
    total_triples = 0

    # Iterate over all possible combinations of A, B, and C
    for i in range(1, a_count + 1):
        for j in range(1, b_count + 1):
            for k in range(1, c_count + 1):
                # Calculate the number of ways to choose i A's, j B's, and k C's
                ways_to_choose = (a_count * (a_count - 1) // 2) * (b_count * (b_count - 1) // 2) * (c_count * (c_count - 1) // 2)
                # Calculate the number of ways to place i A's, j B's, and k C's in the string
                ways_to_place = (a_count + b_count + c_count - i - j - k + 1) * (a_count + b_count + c_count - i - j - k) // 2
                # Calculate the number of valid triples
                valid_triples = ways_to_choose * ways_to_place
                # Add to the total number of triples
                total_triples += valid_triples

    # Multiply by 3^Q and take modulo MOD
    total_triples *= pow(3, q_count, MOD)
    total_triples %= MOD

    return total_triples

