def solve(s):
    n = len(s)
    q = s.count('?')
    if q == 0:
        return count_abc_number(s)

    total_abc = 0
    for i in range(n):
        if s[i] == '?':
            remaining_q = q - 1
            remaining_strings = 3 ** remaining_q
            count = count_abc_number(s[:i] + 'A' + s[i+1:]) + count_abc_number(s[:i] + 'B' + s[i+1:]) + count_abc_number(s[:i] + 'C' + s[i+1:])
            total_abc += count * remaining_strings
            total_abc %= MOD

    return total_abc

