def mod_pow(base, exp):
    result = 1
    base = base % MOD
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % MOD
        exp = exp >> 1
        base = (base * base) % MOD
    return result

def abc_number(S):
    n = len(S)
    A_positions = [i for i in range(n) if S[i] == 'A']
    B_positions = [i for i in range(n) if S[i] == 'B']
    C_positions = [i for i in range(n) if S[i] == 'C']
    Q = S.count('?')

    if not A_positions or not B_positions or not C_positions:
        return 0

    count = 0
    for a in A_positions:
        for b in B_positions:
            if b <= a:
                continue
            for c in C_positions:
                if c <= b:
                    continue
                count += 1

    count *= mod_pow(3, Q)
    return count % MOD

