def can_schedule_matches(N, opponents):
    # Step 1: Build the graph
    graph = defaultdict(list)
    in_degree = [0] * (N + 1)

    for i in range(1, N + 1):
        for j in range(N - 1):
            opponent = opponents[i - 1][j]
            graph[i].append(opponent)
            in_degree[opponent] += 1

    # Step 2: Detect cycles using DFS
    def has_cycle(node, visited, rec_stack):
        visited[node] = True
        rec_stack[node] = True

        for neighbor in graph[node]:
            if not visited[neighbor]:
                if has_cycle(neighbor, visited, rec_stack):
                    return True
            elif rec_stack[neighbor]:
                return True

        rec_stack[node] = False
        return False

    visited = [False] * (N + 1)
    rec_stack = [False] * (N + 1)

    for i in range(1, N + 1):
        if not visited[i]:
            if has_cycle(i, visited, rec_stack):
                return -1

    # Step 3: Perform topological sort to find the minimum number of days
    queue = deque()
    for i in range(1, N + 1):
        if in_degree[i] == 0:
            queue.append(i)

    days = 0
    while queue:
        days += 1
        for _ in range(len(queue)):
            node = queue.popleft()
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

    return days

