import sys
from typing import List, Tuple

def read_input() -> Tuple[int, List[Tuple[int, int]]]:
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    points = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(N)]
    return N, points

def orientation(p: Tuple[int, int], q: Tuple[int, int], r: Tuple[int, int]) -> int:
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if val == 0:
        return 0
    elif val > 0:
        return 1
    else:
        return 2

def convex_hull(points: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if len(points) < 3:
        return points

    points.sort()
    lower = []
    for p in points:
        while len(lower) >= 2 and orientation(lower[-2], lower[-1], p) != 2:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and orientation(upper[-2], upper[-1], p) != 2:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

def circumcircle(p1: Tuple[int, int], p2: Tuple[int, int], p3: Tuple[int, int]) -> Tuple[float, float, float]:
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = p3
    D = 2 * (x1*(y2 - y3) + x2*(y3 - y1) + x3*(y1 - y2))
    Ux = ((x1**2 + y1**2)*(y2 - y3) + (x2**2 + y2**2)*(y3 - y1) + (x3**2 + y3**2)*(y1 - y2)) / D
    Uy = ((x1**2 + y1**2)*(x3 - x2) + (x2**2 + y2**2)*(x1 - x3) + (x3**2 + y3**2)*(x2 - x1)) / D
    radius = ((x1 - Ux)**2 + (y1 - Uy)**2)**0.5
    return Ux, Uy, radius

def main():
    N, points = read_input()
    hull = convex_hull(points)
    min_radius = float('inf')

    for i in range(len(hull)):
        for j in range(i+1, len(hull)):
            for k in range(j+1, len(hull)):
                Ux, Uy, radius = circumcircle(hull[i], hull[j], hull[k])
                min_radius = min(min_radius, radius)

    print(f"{min_radius:.15f}")

if __name__ == "__main__":
    main()
import sys
import math

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def orientation(p, q, r):
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if val == 0:
        return 0  # collinear
    elif val > 0:
        return 1  # clockwise
    else:
        return 2  # counterclockwise

def convex_hull(points):
    n = len(points)
    if n < 3:
        return points

    # Find the leftmost point
    l = 0
    for i in range(1, n):
        if points[i][0] < points[l][0]:
            l = i

    hull = []
    p = l
    while True:
        hull.append(points[p])
        q = (p + 1) % n
        for r in range(n):
            if orientation(points[p], points[q], points[r]) == 2:
                q = r
        p = q
        if p == l:
            break

    return hull

def circumradius(p1, p2, p3):
    a = distance(p1, p2)
    b = distance(p2, p3)
    c = distance(p3, p1)
    s = (a + b + c) / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))
    return (a * b * c) / (4 * area)

def min_circle_radius(points):
    if len(points) == 2:
        return distance(points[0], points[1]) / 2
    elif len(points) == 1:
        return 0

    hull = convex_hull(points)
    n = len(hull)

    if n == 3:
        return circumradius(hull[0], hull[1], hull[2])

    # Brute force for more than 3 points
    min_radius = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                r = circumradius(hull[i], hull[j], hull[k])
                if r < min_radius:
                    min_radius = r

    return min_radius

