from math import sqrt

def circumcircle_radius(x1, y1, x2, y2, x3, y3):
    # Calculate the determinant
    D = 2 * (x1*(y2 - y3) + x2*(y3 - y1) + x3*(y1 - y2))
    if D == 0:
        return float('inf')  # Points are collinear, no circumcircle

    # Calculate the circumcenter (x, y)
    x = ((x1**2 + y1**2) * (y2 - y3) + (x2**2 + y2**2) * (y3 - y1) + (x3**2 + y3**2) * (y1 - y2)) / D
    y = ((x1**2 + y1**2) * (x3 - x2) + (x2**2 + y2**2) * (x1 - x3) + (x3**2 + y3**2) * (x2 - x1)) / D

    # Calculate the radius
    radius = sqrt((x - x1)**2 + (y - y1)**2)
    return radius

def min_enclosing_circle_radius(points):
    n = len(points)
    if n == 2:
        x1, y1 = points[0]
        x2, y2 = points[1]
        return sqrt((x2 - x1)**2 + (y2 - y1)**2) / 2

    min_radius = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                radius = circumcircle_radius(points[i][0], points[i][1], points[j][0], points[j][1], points[k][0], points[k][1])
                if radius < min_radius:
                    min_radius = radius
    return min_radius

