def min_cuts(H, W, K, grid):
    # Initialize the DP array with infinity
    dp = [[float('inf')] * (W + 1) for _ in range(H + 1)]
    dp[0][0] = 0

    # Iterate over each cell in the grid
    for i in range(1, H + 1):
        for j in range(1, W + 1):
            # Calculate the number of white squares in the subgrid (1,1) to (i,j)
            white_squares = sum(grid[x-1][y-1] for x in range(1, i+1) for y in range(1, j+1))

            # If the number of white squares is less than or equal to K, no cuts are needed
            if white_squares <= K:
                dp[i][j] = 0
            else:
                # Try cutting horizontally
                for x in range(1, i):
                    dp[i][j] = min(dp[i][j], dp[x][j] + 1)

                # Try cutting vertically
                for y in range(1, j):
                    dp[i][j] = min(dp[i][j], dp[i][y] + 1)

    return dp[H][W]

