def flood_fill(grid, visited, i, j, H, W):
    if i < 0 or i >= H or j < 0 or j >= W or visited[i][j] or grid[i][j] == '0':
        return 0
    visited[i][j] = True
    count = 1
    count += flood_fill(grid, visited, i + 1, j, H, W)
    count += flood_fill(grid, visited, i - 1, j, H, W)
    count += flood_fill(grid, visited, i, j + 1, H, W)
    count += flood_fill(grid, visited, i, j - 1, H, W)
    return count

def min_cuts(H, W, K, grid):
    visited = [[False] * W for _ in range(H)]
    blocks = []

    for i in range(H):
        for j in range(W):
            if not visited[i][j]:
                block_size = flood_fill(grid, visited, i, j, H, W)
                blocks.append(block_size)

    horizontal_cuts = 0
    vertical_cuts = 0

    for block in blocks:
        if block > K:
            horizontal_cuts += (block - 1) // K
            vertical_cuts += (block - 1) // K

    return horizontal_cuts + vertical_cuts

