from collections import deque

def is_bipartite(grid, H, W, start, color):
    queue = deque([start])
    visited = set([start])
    colors = [color]

    while queue:
        x, y = queue.popleft()
        current_color = colors.pop()

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and (nx, ny) not in visited:
                visited.add((nx, ny))
                if grid[nx][ny] == 1:
                    colors.append(current_color ^ 1)
                else:
                    colors.append(current_color)
                queue.append((nx, ny))

    return True

def min_cuts_to_bipartite(grid, H, W, K):
    cuts = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 1:
                if not is_bipartite(grid, H, W, (i, j), 0):
                    cuts += 1
    return cuts

