    total_layers = 2**N + 1

    # Calculate the number of layers in each level
    layers = [0] * (N + 1)
    layers[0] = 1
    for i in range(1, N + 1):
        layers[i] = 2 * layers[i - 1] + 1

    # Calculate the number of patties in each level
    patties = [0] * (N + 1)
    patties[0] = 1
    for i in range(1, N + 1):
        patties[i] = 2 * patties[i - 1]

