    current_layers = 0
    for i in range(N, -1, -1):
        if current_layers + layers[i] <= X:
            current_layers += layers[i]
        else:
            remaining_layers = X - current_layers
            patty_layers = remaining_layers // 2
            return patties[i] + patty_layers

