def binomial_coefficient(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n - k:
        k = n - k
    coeff = 1
    for i in range(k):
        coeff = coeff * (n - i) % MOD
        coeff = coeff * pow(i + 1, MOD - 2, MOD) % MOD
    return coeff

def sum_of_paths(r1, c1, r2, c2):
    max_n = r2 + c2
    binomials = [0] * (max_n + 1)
    for i in range(max_n + 1):
        binomials[i] = [0] * (i + 1)
        for j in range(i + 1):
            binomials[i][j] = binomial_coefficient(i, j)

    total_sum = 0
    for i in range(r1, r2 + 1):
        for j in range(c1, c2 + 1):
            total_sum = (total_sum + binomials[i + j][i]) % MOD

    return total_sum

