import sys

def floyd_warshall(n, dist):
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    return False
    return True

def min_total_length(n, dist):
    # Create a copy of the distance matrix to avoid modifying the original
    graph = [row[:] for row in dist]

    # Initialize the total length of roads
    total_length = 0

    # Try to find the minimum possible total length of roads
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if i != j and k != i and k != j and dist[i][k] + dist[k][j] == dist[i][j]:
                    # If we can reduce the distance by removing the edge (i, k) and (k, j)
                    graph[i][j] = min(graph[i][j], dist[i][k] + dist[k][j])
                    total_length += dist[i][k] + dist[k][j]
                    dist[i][j] = graph[i][j]

    return total_length

