def can_reach_target(N, S):
    if N == 0:
        return Counter(S) == Counter([1])

    target_counter = Counter(S)
    original_health = 1

    def backtrack(current_counter, current_health, time):
        if time == N:
            return current_counter == target_counter

        for new_health in range(1, current_health):
            current_counter[current_health] -= 1
            current_counter[new_health] += 1
            if backtrack(current_counter, new_health, time + 1):
                return True
            current_counter[current_health] += 1
            current_counter[new_health] -= 1

        return False

    return backtrack(Counter([original_health]), original_health, 1)

