    # Initialize the variables
    variables = {'A': A, 'B': B, 'C': C}
    operations = {'AB': ('A', 'B'), 'AC': ('A', 'C'), 'BC': ('B', 'C')}
    sequence = []

    for choice in choices:
        var1, var2 = operations[choice]
        if variables[var1] > 0:
            variables[var1] -= 1
            variables[var2] += 1
            sequence.append(var1)
        elif variables[var2] > 0:
            variables[var2] -= 1
            variables[var1] += 1
            sequence.append(var2)
        else:
            return "No"

    return "Yes\n" + "\n".join(sequence)

