    def min_cost_to_one_digit(digit):
        dist = [float('inf')] * digits
        dist[digit] = 0
        pq = [(0, digit)]

        while pq:
            current_cost, current_digit = heapq.heappop(pq)
            if current_cost > dist[current_digit]:
                continue
            for neighbor, neighbor_cost in graph[current_digit].items():
                new_cost = current_cost + neighbor_cost
                if new_cost < dist[neighbor]:
                    dist[neighbor] = new_cost
                    heapq.heappush(pq, (new_cost, neighbor))

        return dist[1]

    # Find the minimum cost to convert each digit to 1
    min_costs = [min_cost_to_one_digit(digit) for digit in range(digits)]

    # Calculate the total minimum cost for the wall
    total_cost = 0
    for i in range(1, H + 1):
        for j in range(1, W + 1):
            if wall_grid[i-1][j-1] != -1:
                total_cost += min_costs[wall_grid[i-1][j-1]]

