    def bfs(start_digit):
        queue = deque([(start_digit, 0)])
        visited = set()
        visited.add(start_digit)

        while queue:
            current_digit, cost = queue.popleft()
            if current_digit == '1':
                return cost
            for next_digit in range(10):
                if next_digit != current_digit and (current_digit, next_digit) not in visited:
                    visited.add((current_digit, next_digit))
                    queue.append((next_digit, cost + c[current_digit][next_digit]))
        return float('inf')

    # Find the minimum cost to turn each digit to '1'
    min_cost = 0
    for i in range(1, 10):
        min_cost += bfs(str(i))

    # Calculate the total minimum MP required for the wall
    total_mp = 0
    for i in range(1, H + 1):
        for j in range(1, W + 1):
            if A[i][j] != -1:
                total_mp += min_cost

    return total_mp

