def count_unnecessary_cards(N, K, a):
    # Initialize DP array
    dp = [False] * (K + 1)
    dp[0] = True

    # Fill DP array
    for num in a:
        for j in range(K, num - 1, -1):
            dp[j] = dp[j] or dp[j - num]

    # Check unnecessary cards
    unnecessary_count = 0
    for i in range(N):
        # Check if removing card i makes all good subsets still good
        if all(dp[j] or not dp[j - a[i]] for j in range(K + 1)):
            unnecessary_count += 1

    return unnecessary_count

