    def light_from_square(x, y):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        lit = 1  # The square itself is lit
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            while 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '.':
                lit += 1
                nx += dx
                ny += dy
        return lit

