MOD = 1000000007

def count_ways(N, sardines):
    if N == 1:
        return 2

    dp = [[0, 0] for _ in range(N + 1)]
    dp[1][0] = 1  # Not choosing the first sardine
    dp[1][1] = 1  # Choosing the first sardine

    for i in range(2, N + 1):
        dp[i][0] = (dp[i-1][0] + dp[i-1][1]) % MOD  # Not choosing the i-th sardine
        dp[i][1] = dp[i-1][0]  # Choosing the i-th sardine, so the previous one must not be chosen

    return (dp[N][0] + dp[N][1]) % MOD

