def max_independent_set(n, sardines):
    if n == 1:
        return 2
    if n == 2:
        a1, b1 = sardines[0]
        a2, b2 = sardines[1]
        if a1 * a2 + b1 * b2 == 0:
            return 2
        else:
            return 4

    dp = [0] * (n + 1)
    dp[1] = 2
    dp[2] = 4 if sardines[0][0] * sardines[1][0] + sardines[0][1] * sardines[1][1] != 0 else 2

    for i in range(3, n + 1):
        dp[i] = dp[i-1]
        for j in range(i-2, -1, -1):
            if sardines[j][0] * sardines[i-1][0] + sardines[j][1] * sardines[i-1][1] != 0:
                dp[i] = max(dp[i], dp[j] + 1)
                break

    return dp[n] % MOD

