from collections import deque

def paint_grid(H, W, N, counts):
    grid = [[0] * W for _ in range(H)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W and grid[x][y] == 0

    def bfs(start_x, start_y, color):
        queue = deque([(start_x, start_y)])
        grid[start_x][start_y] = color
        while queue:
            x, y = queue.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny):
                    grid[nx][ny] = color
                    queue.append((nx, ny))

    color_index = 0
    for count in counts:
        for _ in range(count):
            found = False
            for i in range(H):
                for j in range(W):
                    if grid[i][j] == 0:
                        bfs(i, j, color_index + 1)
                        found = True
                        break
                if found:
                    break
            color_index += 1

    return grid

