def flood_fill(grid, x, y, color, H, W):
    if x < 0 or x >= H or y < 0 or y >= W or grid[x][y] != 0:
        return
    grid[x][y] = color
    flood_fill(grid, x + 1, y, color, H, W)
    flood_fill(grid, x - 1, y, color, H, W)
    flood_fill(grid, x, y + 1, color, H, W)
    flood_fill(grid, x, y - 1, color, H, W)

